func TestAccount(t *testing.T) {
	endpoints := []string{
		"192.168.0.2:2379",
		"192.168.0.3:2379",
		"192.168.0.4:2379",
	}

	_, ok := GetAccount(endpoints)
	assert.False(t, ok)

	AddAccount(endpoints, "foo", "bar")
	account, ok := GetAccount(endpoints)
	assert.True(t, ok)
	assert.Equal(t, "foo", account.User)
	assert.Equal(t, "bar", account.Pass)

	AddAccount(endpoints, "foo", "updated")
	account, ok = GetAccount(endpoints)
	assert.True(t, ok)
	assert.Equal(t, "foo", account.User)
	assert.Equal(t, "updated", account.Pass)
}
